// Keep playing in memory when browser storage is unavailable; keys remain unchanged.
const multanStorage=(()=>{const memory=new Map();let warned=false;function warn(){if(warned)return;warned=true;const show=()=>{const el=document.createElement('p');el.setAttribute('role','status');el.style.cssText='position:fixed;bottom:0;left:0;right:0;z-index:1000;margin:0;padding:8px 12px;background:#fff2d9;color:#6e4b35;font:14px/1.4 system-ui';el.textContent='Прогресс не сохраняется: браузер запретил хранилище или закончилось место.';document.body.append(el);};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',show);else show();}return {getItem(k){if(memory.has(k))return memory.get(k);try{return localStorage.getItem(k);}catch(e){warn();return null;}},setItem(k,v){memory.set(k,String(v));try{localStorage.setItem(k,v);}catch(e){warn();}},removeItem(k){memory.set(k,null);try{localStorage.removeItem(k);}catch(e){warn();}}};})();
function multanIndex(key,length){const raw=multanStorage.getItem(key),n=Number(raw);if(raw==='null'){multanStorage.removeItem(key);return 0;}return Number.isFinite(n)?Math.max(0,Math.min(length-1,Math.trunc(n))):0;}
function readMultanAnswers(n){const read=k=>{try{const v=JSON.parse(multanStorage.getItem(k)||'{}');return v&&typeof v==='object'&&!Array.isArray(v)?v:{};}catch(e){return {};}};if(n!==1)return read('multan-answers-'+n);const merged={...read('multan-answers-1'),...read('multan-chapter1-answers')};multanStorage.setItem('multan-chapter1-answers',JSON.stringify(merged));multanStorage.setItem('multan-answers-1',JSON.stringify(merged));return merged;}
function saveMultanAnswers(n,answers){multanStorage.setItem(n===1?'multan-chapter1-answers':'multan-answers-'+n,JSON.stringify(answers));if(n===1)multanStorage.setItem('multan-answers-1',JSON.stringify(answers));}
let activeChapter=1;
let data=[],i=0,busy=false;const $=x=>document.getElementById(x);const notes={village:'Старый Мултан — село, где начинается действие романа. В повествовании подчёркнуты леса, возвышенность и речка Мултанка.',forest:'В осеннем пейзаже важны рябина, берёзы, ели и сосны. Рябина здесь — предмет конкретного сюжетного эпизода, а не доказанный этнографический символ.',spring:'У родника стоял сруб, защищавший воду от скота. Неподалёку находились ветла и небольшая баня, которую Григорий топил по-чёрному.',memory:'Воспоминание Григория относится к его детству. Это отдельный временной пласт повествования.',interrogation:'Урядник — нижний чин сельской полиции Российской империи. В игре показано отношение героя к власти; правовые подробности будут проверяться отдельно.'};let sections=[["Панорама деревни",0],["Встреча у родника",6],["Обида Григория",10],["Учитель и Григорий",14],["У родника",24],["Первый допрос",30],["Отправка в Трык",41],["В Трыке",54],["Лосев у старосты",60],["Возвращение из Трыка",72],["Дома с матерью",75],["Встреча у Лосева",85]];const portraits={"Григорий":"grigory","Дуняша":"dunyasha","Илья Фомич":"teacher","Акмар":"akmar","Никифор":"nikifor","Степан Журавль":"stepan_zhuravl","Агафон Демьянович":"uryadnik","Дьякон":"deacon","Ульяна":"ulyana","Степан Лосев":"losev_portrait","Бектэмыр":"bektemyr","Игнат Букин":"ignat","Алёна":"alyona","Иван Красный":"ivan_krasny","Мать Дуняши":"akmar_mother"};let currentCharacter='';function showPortrait(b){const id=portraits[b.speaker];const box=$('character'),pic=$('characterImg'),mini=$('speakerPortrait');if(b.kind==='n'||!id){box.classList.remove('shown');mini.style.display='none';currentCharacter='';return;}const src='assets/'+id+'.webp';if(currentCharacter!==id){box.classList.remove('shown');pic.src=src;currentCharacter=id;requestAnimationFrame(()=>box.classList.add('shown'));}else box.classList.add('shown');$('characterName').textContent=b.speaker;mini.src=src;mini.alt='Портрет: '+b.speaker;mini.style.display='block';}function render(){const b=data[i];showPortrait(b);$('sceneLabel').textContent=b.scene;$('who').textContent=b.kind==='n'?'✦ Михаил Петров':b.speaker;$('who').className='who '+(b.kind==='n'?'narrator':'');$('line').textContent=b.text;$('counter').textContent=`${i+1} / ${data.length}`;$('pct').textContent=Math.round((i+1)/data.length*100)+'%';$('fill').style.width=((i+1)/data.length*100)+'%';$('prev').disabled=i===0;$('next').textContent=i===data.length-1?'Начать заново ↺':'Далее →';$('chapters').innerHTML=sections.map(([name,start],k)=>`<button class="${i>=start&&(k===sections.length-1||i<sections[k+1][1])?'active':''}" data-start="${start}">${k+1}. ${name}</button>`).join('');document.querySelectorAll('[data-start]').forEach(el=>el.onclick=()=>go(+el.dataset.start));if(typeof activeChapter==='undefined'||activeChapter===1)multanStorage.setItem('stary-multan-chapter1-final',i)}function go(target){if(busy)return;if(target>=data.length)target=0;if(target<0)return;const old=data[i],next=data[target];const changed=old.bg!==next.bg;if(changed&&$('motion').checked){busy=true;$('transition').classList.add('visible');setTimeout(()=>{i=target;setBg();render();setTimeout(()=>{$('transition').classList.remove('visible');busy=false},120)},420)}else{i=target;if(changed)setBg();render()}}function setBg(){$('sceneBg').style.backgroundImage="url('assets/"+data[i].bg+".webp')";$('stage').classList.remove('play');void $('stage').offsetWidth;$('stage').classList.add('play')}function popup(title,html){$('modalTitle').textContent=title;$('modalBody').innerHTML=html;$('modal').showModal()}data=[{"bg":"village","speaker":"Михаил Петров","text":"На возвышенности, окружённой лесами, раскинулось село Старый Мултан. Под горой текла Мултанка.","scene":"Панорама деревни","kind":"n"},{"bg":"village","speaker":"Михаил Петров","text":"Осенью лес пылал золотом и багрянцем. Между соснами и елями желтели берёзы, краснела рябина.","scene":"Поздняя осень","kind":"n"},{"bg":"forest","speaker":"Михаил Петров","text":"Под вечер молодой Григорий пришёл к речке с топором. Он срубил две сухие ёлочки и остановился, задумавшись о своей жизни.","scene":"Григорий идёт через лес","kind":"n"},{"bg":"forest","speaker":"Михаил Петров","text":"Он сорвал несколько кистей рябины, взвалил деревца на плечо и пошёл к берегу.","scene":"Переход к речке","kind":"n"},{"bg":"spring","speaker":"Михаил Петров","text":"Перебравшись через Мултанку по гибким жердям, Григорий растопил небольшую баню. Рядом, под старой ветлой, бил родник.","scene":"У бани и родника","kind":"n"},{"bg":"spring","speaker":"Михаил Петров","text":"К роднику подошла Дуняша с коромыслом. Она напевала тихую песню и украдкой поглядывала на Григория.","scene":"Появление Дуняши","kind":"n"},{"bg":"spring","speaker":"Григорий","text":"Дуняша!.. Помогла бы. Завернула бы сюда да занесла ведерко водицы.","scene":"Встреча у родника","kind":"d"},{"bg":"spring","speaker":"Дуняша","text":"Завернешь — да еще угодишь куда не следует…","scene":"Дуняша отвечает","kind":"d"},{"bg":"spring","speaker":"Михаил Петров","text":"Григорий протянул девушке рябину. Он хотел угостить её, но она рассмеялась над таким подарком.","scene":"Неловкий подарок","kind":"n"},{"bg":"spring","speaker":"Дуняша","text":"Парни девок конфетами угощают, а ты рябиной.","scene":"Шутка Дуняши","kind":"d"},{"bg":"spring","speaker":"Михаил Петров","text":"Григорий долго смотрел вслед Дуняше. Ему показалось, что девушка смеётся над его бедностью. Обиженный, он швырнул рябину под ноги; красные ягоды рассыпались по земле.","scene":"Обида Григория","kind":"n"},{"bg":"spring","speaker":"Григорий","text":"Посмешищем стал! Не только для богачей, но и для таких, как Дуня…","scene":"Обида Григория","kind":"d"},{"bg":"memory","speaker":"Михаил Петров","text":"Сидя перед баней, Григорий вновь переживает давнее горе: гибель отца и то, как изменилась после этого его жизнь.","scene":"Тяжёлое воспоминание","kind":"n"},{"bg":"spring","speaker":"Михаил Петров","text":"На плечо Григория легла чья-то рука. Он обернулся и узнал голос сельского учителя.","scene":"Возвращение к бане","kind":"n"},{"bg":"spring","speaker":"Илья Фомич","text":"Что ж ты голову повесил, молодец?","scene":"Учитель и Григорий","kind":"d"},{"bg":"spring","speaker":"Григорий","text":"Здравствуйте, Илья Фомич!","scene":"Учитель и Григорий","kind":"d"},{"bg":"spring","speaker":"Илья Фомич","text":"Ты, друг милый, грустные мысли гони от себя, поддашься им — жизнь тебя растопчет.","scene":"Разговор о жизни","kind":"d"},{"bg":"spring","speaker":"Григорий","text":"Под вами земля покрепче, Илья Фомич.","scene":"Разговор о жизни","kind":"d"},{"bg":"spring","speaker":"Илья Фомич","text":"Земля под нами, Григорий, одинаково зыбкая — того гляди не устоишь…","scene":"Разговор о жизни","kind":"d"},{"bg":"spring","speaker":"Михаил Петров","text":"Учитель говорит о тяжёлой жизни крестьян, о Буграше, Букине и Камаеве. Он спрашивает, почему трудящиеся люди живут беднее богатых.","scene":"Откуда берётся бедность","kind":"n"},{"bg":"spring","speaker":"Илья Фомич","text":"Ты когда-нибудь подумай об этом, Григорий. Крепко подумай!","scene":"Откуда берётся бедность","kind":"d"},{"bg":"spring","speaker":"Григорий","text":"Нужда заставляет, Илья Фомич.","scene":"Прощание с учителем","kind":"d"},{"bg":"spring","speaker":"Илья Фомич","text":"Нужда, она многим шею гнёт… Ты в свободное время заходи ко мне. Посидим, поговорим…","scene":"Прощание с учителем","kind":"d"},{"bg":"spring","speaker":"Михаил Петров","text":"Слова учителя удивили Григория. Истопив баню, он собрался домой, но внезапно остановился.","scene":"После разговора","kind":"n"},{"bg":"spring","speaker":"Михаил Петров","text":"У родника стоял пьяный дьякон. Перед ним замерла огромная чёрная собака. Дьякон размахивал руками и кричал на неё.","scene":"У родника","kind":"n"},{"bg":"spring","speaker":"Дьякон","text":"Изыди, сатана!.. Сгинь!..","scene":"У родника","kind":"d"},{"bg":"spring","speaker":"Михаил Петров","text":"Дьякон, пытаясь прогнать чёрную собаку, потерял равновесие и упал в родник. Григорий бросился к воде, долго пытался вытащить его, но было поздно: дьякон уже не подавал признаков жизни.","scene":"Несчастный случай","kind":"n"},{"bg":"village","speaker":"Михаил Петров","text":"Григорий побежал сообщить о случившемся старосте. По дороге он встретил Акмара — деда Дуняши — и рассказал ему о беде.","scene":"Совет Акмара","kind":"n"},{"bg":"village","speaker":"Акмар","text":"Ты об этом молчи, Гриша. Никому ни слова. Затаскают по судам…","scene":"Совет Акмара","kind":"d"},{"bg":"village","scene":"Молчание","speaker":"Михаил Петров","text":"Григорий послушался Акмара и никому не рассказал о происшествии, даже матери. Но тревога не оставляла его.","kind":"n"},{"bg":"interrogation","speaker":"Михаил Петров","text":"На следующий день урядник велел перенести тело в пожарный сарай и начал расследование. Григория вызвали на съезжую. Войдя в избу, он остановился у порога; урядник сидел за столом.","scene":"Первый допрос","kind":"n"},{"bg":"interrogation","speaker":"Агафон Демьянович","text":"Скажи, Григорий Дмитриев: как ты утопил дьякона?","scene":"Первый допрос","kind":"d"},{"bg":"interrogation","speaker":"Григорий","text":"Не толкал я, ваше благородие, сам упал, пьяный крепко.","scene":"Первый допрос","kind":"d"},{"bg":"interrogation","speaker":"Агафон Демьянович","text":"Не ври! Скажи: зачем убил?","scene":"Первый допрос","kind":"d"},{"bg":"interrogation","speaker":"Григорий","text":"Не убил, ваше благородие. Зачем убивать?","scene":"Первый допрос","kind":"d"},{"bg":"interrogation","speaker":"Михаил Петров","text":"Каждый новый вопрос пугает Григория всё сильнее. Он не ожидал, что попытка помочь утопающему обернётся обвинением.","scene":"Первый допрос","kind":"n"},{"bg":"interrogation","speaker":"Михаил Петров","text":"Урядник заинтересовался не только смертью дьякона, но и тем, что говорил Илья Фомич о Пугачёве.","scene":"Разговор об учителе","kind":"n"},{"bg":"interrogation","speaker":"Агафон Демьянович","text":"Расскажи по порядку, что говорил учитель о Пугачёве.","scene":"Разговор об учителе","kind":"d"},{"bg":"interrogation","speaker":"Григорий","text":"Илья Фомич сначала ушёл, потом дьякон пришёл, ваше благородие. Он ничего не виноват.","scene":"Разговор об учителе","kind":"d"},{"bg":"interrogation","speaker":"Михаил Петров","text":"Григорий понимает, что обмолвился о Пугачёве напрасно: урядник ищет повод обвинить учителя.","scene":"Разговор об учителе","kind":"n"},{"bg":"interrogation","speaker":"Григорий","text":"Только и было. Плохо не говорил.","scene":"Разговор об учителе","kind":"d"},{"bg":"road","speaker":"Михаил Петров","text":"Урядник отправляет Григория в волостное селение Трык в сопровождении понятых — Никифора и Степана по прозвищу Журавль.","scene":"Отправка в Трык","kind":"n"},{"bg":"road","speaker":"Михаил Петров","text":"Григорий идёт через деревню, не поднимая глаз. Больше всего он боится встретить Дуняшу.","scene":"Дорога через Мултан","kind":"n"},{"bg":"road","speaker":"Михаил Петров","text":"На спуске с горы Дуняша видит Григория и сопровождающих. По их лицам она понимает, что случилась беда.","scene":"Встреча с Дуняшей","kind":"n"},{"bg":"road","speaker":"Никифор","text":"Вот, убийцу нашли. Они пьяные будут тонуть, а наш брат отвечай…","scene":"Встреча с Дуняшей","kind":"d"},{"bg":"road","speaker":"Михаил Петров","text":"Никифор замечает, что Григорию нужно поговорить с Дуняшей, и отводит Степана в сторону.","scene":"Встреча с Дуняшей","kind":"n"},{"bg":"road","speaker":"Григорий","text":"Прощай, Дуня. Может, больше не увидимся. Все мои думы были о тебе, а теперь…","scene":"Прощание","kind":"d"},{"bg":"road","speaker":"Дуняша","text":"Куда же тебя?","scene":"Прощание","kind":"d"},{"bg":"road","speaker":"Михаил Петров","text":"Григорий не отвечает: только машет рукой и уходит за понятыми.","scene":"Прощание","kind":"n"},{"bg":"road","speaker":"Никифор","text":"И за что только нас таскают! Если и дальше так будет, обозлится народ…","scene":"Дорога в Трык","kind":"d"},{"bg":"road","speaker":"Григорий","text":"Дядя Никифор, а кто такой Пугач?","scene":"Разговор о Пугачёве","kind":"d"},{"bg":"road","speaker":"Никифор","text":"За крестьян он стоял, за таких, как мы, бедняков, вот кто такой был Пугач. Против бояр и против самого царя шёл.","scene":"Разговор о Пугачёве","kind":"d"},{"bg":"road","speaker":"Михаил Петров","text":"Никифор рассказывает о восстании Пугачёва и своих поездках по Волге, вспоминает Казань, Симбирск и Самару.","scene":"Разговор о Пугачёве","kind":"n"},{"bg":"road","scene":"Рассказ Никифора","speaker":"Михаил Петров","text":"Никифор долго говорил о Пугачёве: вспоминал заводы Урала, города на Волге и поражение восстания. В его рассказе действительные события перемешивались с народными преданиями.","kind":"n"},{"bg":"interrogation","speaker":"Михаил Петров","text":"В Трыке Никифор и Степан дожидались урядника до темноты. Вернувшись пьяным, тот снова допрашивал Григория, бил его головой о стену, а затем приказал запереть.","scene":"В Трыке","kind":"n"},{"bg":"cell","scene":"Ночь в каталажке","speaker":"Михаил Петров","text":"Ночь Григорий провёл в холодной каменной каталажке. В двух маленьких оконцах были выбиты стёкла. Чтобы согреться, он вставал с нар и прыгал на месте, но сон не приходил.","kind":"n"},{"bg":"cell","scene":"Мысли заключённого","speaker":"Михаил Петров","text":"В темноте Григорий думал о каторге и людях, которых уводят далеко от дома. Он ещё не знал, когда сможет вернуться.","kind":"n"},{"bg":"village","speaker":"Михаил Петров","text":"Тем временем Ульяна ходит по соседям и пытается узнать, за что увели её сына.","scene":"Ночь в деревне","kind":"n"},{"bg":"village","speaker":"Ульяна","text":"За что увели моего сына, может, вы, дорогие, скажете мне?","scene":"Ночь в деревне","kind":"d"},{"bg":"village","speaker":"Михаил Петров","text":"Акмар всю ночь корит себя за совет молчать. Он давно думал выдать Дуняшу за Григория и теперь боится, что сам погубил парня.","scene":"Раскаяние Акмара","kind":"n"},{"bg":"village","speaker":"Михаил Петров","text":"Наутро Степан Лосев приходит к старосте Бектэмыру. Его дочь и дочь просвирни видели, как дьякон упал сам. Лосев просит помочь невиновному.","scene":"Лосев у старосты","kind":"n"},{"bg":"village","speaker":"Степан Лосев","text":"Дьякон сам упал в родник. Моя дочка видела. Просвирина дочка тоже видела…","scene":"Лосев у старосты","kind":"d"},{"bg":"village","speaker":"Бектэмыр","text":"Кто же это поверит девчонкам?","scene":"Лосев у старосты","kind":"d"},{"bg":"village","speaker":"Степан Лосев","text":"Но ты же староста.","scene":"Лосев у старосты","kind":"d"},{"bg":"village","speaker":"Бектэмыр","text":"Если жалко, сам сходи, объясни уряднику. Разве я тебя держу?","scene":"Лосев у старосты","kind":"d"},{"bg":"village","speaker":"Михаил Петров","text":"Лосев зашёл в школу и дождался конца урока. Илья Фомич вместе с ним расспросил девочек, видевших падение дьякона, а затем отправился в Трык.","scene":"В школе","kind":"n"},{"bg":"interrogation","speaker":"Агафон Демьянович","text":"Ну, а если бы они сказали, что дьякона утопил сам учитель? Тогда как?","scene":"Учитель у урядника","kind":"d"},{"bg":"interrogation","speaker":"Илья Фомич","text":"Говорить напрасно они не будут, Агафон Демьяныч.","scene":"Учитель у урядника","kind":"d"},{"bg":"interrogation","speaker":"Михаил Петров","text":"Учитель напоминает уряднику о другом деле, где тот поверил ребёнку. Урядник злится и начинает подозревать самого учителя.","scene":"Учитель у урядника","kind":"n"},{"bg":"interrogation","speaker":"Агафон Демьянович","text":"Дмитриев уже успел кое-что рассказать о вас. Скоро мы с вами встретимся.","scene":"Учитель у урядника","kind":"d"},{"bg":"interrogation","scene":"Угроза учителю","speaker":"Илья Фомич","text":"Дать вам волю, вы бы пересажали весь народ.","kind":"d"},{"bg":"interrogation","scene":"После разговора","speaker":"Михаил Петров","text":"Илья Фомич вышел от урядника, возмущённый его угрозами. Защитить Григория оказалось труднее, чем он надеялся.","kind":"n"},{"bg":"road","speaker":"Михаил Петров","text":"Больше недели Григорий провёл в каталажке. Домой в Старый Мултан он вернулся ночью. Обстоятельства его освобождения автор подробно не описывает.","scene":"Возвращение из Трыка","kind":"n"},{"bg":"village","speaker":"Михаил Петров","text":"Дорога из Трыка осталась позади. После долгого заключения Григорий снова увидел родную деревню.","scene":"Снова в Старом Мултане","kind":"n"},{"bg":"home","speaker":"Михаил Петров","text":"Вернувшись домой, Григорий не позволил матери даже вскипятить чай: поел картошки с кислой капустой и забрался на полати. Уснуть он долго не мог.","scene":"Дома после возвращения","kind":"n"},{"bg":"home","speaker":"Михаил Петров","text":"Скрипели доски полатей. Полоса лунного света лежала на полу. Ульяна тоже не спала, чувствуя, как тяжело сыну.","scene":"Дома с матерью","kind":"n"},{"bg":"home","speaker":"Ульяна","text":"Сынок, чего не спишь?","scene":"Дома с матерью","kind":"d"},{"bg":"home","speaker":"Григорий","text":"Думаю, мама. Илью Фомича жалко. Загубят они его, в острог упрячут.","scene":"Дома с матерью","kind":"d"},{"bg":"home","speaker":"Ульяна","text":"А урядник тебя не шибко пугал? Для них ведь — что собаки, что мы. Бил, поди?","scene":"Дома с матерью","kind":"d"},{"bg":"home","speaker":"Григорий","text":"Теперь я всё понял: они просто через меня хотели зацепиться за учителя.","scene":"Дома с матерью","kind":"d"},{"bg":"home","speaker":"Ульяна","text":"Другую, видно, песню поёт?","scene":"Дома с матерью","kind":"d"},{"bg":"home","speaker":"Григорий","text":"Он за нас, за народ стоит. А это им не по шерсти.","scene":"Дома с матерью","kind":"d"},{"bg":"home","scene":"Разговор с матерью","speaker":"Ульяна","text":"Спи-ка, сынок, спи. Такой умный человек, как наш учитель, не поддастся им.","kind":"d"},{"bg":"home","scene":"Разговор с матерью","speaker":"Григорий","text":"Кулак урядника одинаков для всех — и для ученых, и для нашего брата.","kind":"d"},{"bg":"home","scene":"Тревога Ульяны","speaker":"Михаил Петров","text":"Ульяна испугалась гневных слов сына. Григорий же всё сильнее задумывался о том, почему крестьяне вынуждены терпеть несправедливость.","kind":"n"},{"bg":"losev","speaker":"Михаил Петров","text":"На другой день, когда стемнело, Степан Лосев позвал Григория к себе: там ждал Илья Фомич. В избе учитель разговаривал с Петрованом из соседней деревни Анык.","scene":"Встреча у Лосева","kind":"n"},{"bg":"losev","speaker":"Илья Фомич","text":"Говори прямо: здорово бил?","scene":"Встреча у Лосева","kind":"d"},{"bg":"losev","speaker":"Григорий","text":"Порядком надавал…","scene":"Встреча у Лосева","kind":"d"},{"bg":"losev","speaker":"Илья Фомич","text":"Ну, коль смеёшься, значит, рёбра целы.","scene":"Встреча у Лосева","kind":"d"},{"bg":"losev","speaker":"Михаил Петров","text":"К разговору присоединяется батрак Игнат Букин. Учитель предлагает всем задуматься, почему бедняки вынуждены терпеть побои, подати и бесправие.","scene":"Встреча у Лосева","kind":"n"},{"bg":"losev","speaker":"Григорий","text":"Коль не поднимется новый Пугач, всегда будет так.","scene":"Разговор о свободе","kind":"d"},{"bg":"losev","speaker":"Михаил Петров","text":"Учитель рассказывает о крестьянских волнениях и отмене крепостного права. Его слова пугают Григория, но заставляют слушателей задуматься.","scene":"Разговор о свободе","kind":"n"},{"bg":"losev","speaker":"Игнат Букин","text":"Если крестьяне освободились от помещика, тогда зачем им платить за землю?","scene":"Разговор о свободе","kind":"d"},{"bg":"losev","scene":"Крестьянская реформа","speaker":"Илья Фомич","text":"После манифеста крестьяне освободились от помещика, но вместе с тем их освободили и от земли.","kind":"d"},{"bg":"losev","scene":"Выкупные платежи","speaker":"Михаил Петров","text":"Учитель объясняет, что освобождённым крестьянам приходилось выкупать землю. Он приводит расчёты по Вятской губернии, и слушатели поражены размером платежей.","kind":"n"},{"bg":"losev","speaker":"Михаил Петров","text":"Илья Фомич достаёт журнал «Северный вестник» и приводит сведения о податях и недоимках в Вятской губернии.","scene":"Подати и недоимки","kind":"n"},{"bg":"losev","speaker":"Петрован","text":"Слышал, Авдеич? Чем будем платить?","scene":"Подати и недоимки","kind":"d"},{"bg":"losev","speaker":"Степан Лосев","text":"Есть лошадь — лошадь уведут, нет лошади — корову уведут или овец.","scene":"Подати и недоимки","kind":"d"},{"bg":"losev","speaker":"Михаил Петров","text":"Разговор переходит к давней тяжбе между мултанцами и аныкцами за землю, межеванию и лесам, закреплённым за казной и лесопромышленниками.","scene":"Земельная тяжба","kind":"n"},{"bg":"losev","speaker":"Илья Фомич","text":"Вы когда-нибудь думали о том, почему между мултанцами и аныкцами уже больше двадцати лет идёт тяжба за землю?","scene":"Земельная тяжба","kind":"d"},{"bg":"losev","speaker":"Михаил Петров","text":"Беседа о крестьянской нужде в избе Лосева продолжается до полуночи.","scene":"Поздний вечер","kind":"n"}];const savedChapterOne=multanStorage.getItem('multan-progress-1');i=multanIndex(savedChapterOne!==null&&savedChapterOne!=='null'&&Number.isFinite(Number(savedChapterOne))?'multan-progress-1':'stary-multan-chapter1-final',data.length);setBg();render();$('next').onclick=()=>go(i+1);$('prev').onclick=()=>go(i-1);$('reset').onclick=()=>go(0);$('help').onclick=()=>popup('Справка','<p>Читайте текст рассказчика и реплики героев. Нажимайте «Далее» или клавишу →. При смене места действия изображение плавно затемняется.</p><p>Слева можно перейти к отдельным эпизодам. Прогресс сохраняется в браузере.</p><p>Откройте вкладку «Контекст» для пояснений к событиям или «Вопрос» для проверки понимания прочитанного.</p>');$('close').onclick=()=>$('modal').close();document.addEventListener('keydown',e=>{if($('modal').open)return;if(e.key==='ArrowRight'||e.key===' '){e.preventDefault();go(i+1)}if(e.key==='ArrowLeft')go(i-1)});

