let studyNotes={
 road:['Дорога в Трык','По дороге Никифор рассказывает Григорию о Пугачёве. Его рассказ соединяет исторические сведения и народные предания.','Что Григорий узнаёт из разговора с Никифором?'],
 cell:['Каталажка','По тексту романа каталажка была каменной, с выбитыми стёклами в двух маленьких окнах. Художественный фон — реконструкция, не фотография конкретного здания.','Какие детали помогают ощутить холод и страх заключённого?'],
 losev:['Дом Лосева','В избе Степана Лосева крестьяне обсуждают реформу, выкупные платежи и земельные споры.','Почему этот разговор меняет представления Григория о мире?'],
 home:['Дом Григория','Григорий возвращается ночью после более чем недельного заключения. Мать и сын тревожатся о судьбе учителя.','Что Григорий понял после допросов?'],
 village:['Место действия','Старый Мултан — село, с которого начинается действие романа. Лес, река и деревенская жизнь становятся частью истории героев.','Как автор знакомит нас с местом действия?'],
 forest:['Повседневный труд','Григорий занят обычной крестьянской работой. Эти подробности помогают понять условия жизни героя до драматических событий.','Какие занятия Григория показаны в начале?'],
 spring:['Родник','Родник — место встречи Григория и Дуняши. Позднее события у родника приобретают совершенно другой смысл.','Как меняется значение одного и того же места?'],
 memory:['Воспоминание','Рассказ о прошлом Григория объясняет, почему вопросы бедности и несправедливости так болезненны для него.','Что читатель узнаёт о детстве героя?'],
 interrogation:['Урядник','Урядник — должностное лицо сельской полиции Российской империи. В этой сцене особенно заметна разница в положении крестьянина и представителя власти.','Как ведут себя участники допроса?']
};
let studyQuestions=[{"from":8,"q":"Чем Григорий хотел угостить Дуняшу?","a":["Рябиной","Конфетами","Яблоками"],"c":0,"why":"Он предложил Дуняше кисти рябины."},{"from":29,"q":"Почему Григорий промолчал о гибели дьякона?","a":["Потому что не видел происшествия","По совету Акмара","По просьбе учителя"],"c":1,"why":"Акмар испугался возможных судебных неприятностей."},{"from":41,"q":"Куда отправили Григория?","a":["В Трык","В Казань","В Ижевск"],"c":0,"why":"Его отправили в волостное селение Трык."},{"from":55,"q":"Какая деталь каталажки подчёркивает тяжесть заключения?","a":["Каменные стены и выбитые стёкла","Тёплая печь","Большая светлая комната"],"c":0,"why":"В романе каталажка каменная, холодная, с выбитыми стёклами."},{"from":60,"q":"Кто видел падение дьякона?","a":["Никифор и Степан","Дочь Лосева и дочь просвирни","Учитель и Акмар"],"c":1,"why":"О происшествии рассказали две девочки."},{"from":72,"q":"Сколько времени Григорий провёл в каталажке?","a":["Одну ночь","Больше недели","Целый год"],"c":1,"why":"Автор прямо пишет, что Григорий просидел там больше недели."},{"from":89,"q":"Что обсуждают в доме Лосева?","a":["Подати, землю и крестьянскую нужду","Свадьбу Дуняши","Охоту"],"c":0,"why":"Разговор посвящён крестьянской реформе, податям и земле."}];
let studyTab='fact', studyAnswers={};
studyAnswers=readMultanAnswers(1);
function renderStudy(){
 const item=data[i],note=studyNotes[item.bg]||studyNotes.village;
 $('note').hidden=studyTab!=='fact';$('quizCard').hidden=studyTab!=='quiz';$('archiveCard').hidden=studyTab!=='archive';
 $('tabFact').classList.toggle('selected',studyTab==='fact');$('tabQuiz').classList.toggle('selected',studyTab==='quiz');$('tabArchive').classList.toggle('selected',studyTab==='archive');
 $('note').innerHTML='<div class="tag">Книга и эпоха</div><h4>'+note[0]+'</h4><p>'+note[1]+'</p><div class="reflection"><b>Подумайте:</b> '+note[2]+'</div>';
 const available=studyQuestions.map((q,k)=>({...q,k})).filter(q=>i>=q.from);const q=available[available.length-1];
 if(!q){$('quizCard').innerHTML='<p>Вопросы будут появляться по мере чтения.</p>';return}
 const answer=studyAnswers[q.k];
 $('quizCard').innerHTML='<div class="tag">Вопрос '+(q.k+1)+' из '+studyQuestions.length+'</div><p class="question">'+q.q+'</p>'+q.a.map((a,k)=>'<button class="answer '+(answer===k?(k===q.c?'right':'wrong'):'')+'" data-choice="'+k+'" '+(answer!==undefined?'disabled':'')+'>'+a+'</button>').join('')+(answer!==undefined?'<p class="explanation">'+(answer===q.c?'Верно! ':'')+q.why+'</p>':'<p class="quiz-hint">Выберите один ответ. Чтение можно продолжать в любом случае.</p>')+'<button class="retry">Ответить заново</button>';
 $('quizCard').querySelectorAll('[data-choice]').forEach(el=>el.onclick=()=>{studyAnswers[q.k]=Number(el.dataset.choice);saveMultanAnswers(1,studyAnswers);renderStudy()});
 $('quizCard').querySelector('.retry').onclick=()=>{delete studyAnswers[q.k];saveMultanAnswers(1,studyAnswers);renderStudy()};
}
$('tabFact').onclick=()=>{studyTab='fact';renderStudy()};
$('tabQuiz').onclick=()=>{studyTab='quiz';renderStudy()};$('tabArchive').onclick=()=>{studyTab='archive';renderStudy()};
$('quizOpen').onclick=()=>{studyTab='quiz';renderStudy()};
const renderStory=render;render=function(){renderStory();renderStudy()};
renderStudy();


