const chapterTwoData=[{"bg": "late_autumn", "scene": "Поздняя осень", "speaker": "Михаил Петров", "text": "Золотая осень прошла. Небо затянули тяжёлые облака, холодные дожди сменялись ветром, а дни становились всё короче.", "kind": "n"}, {"bg": "grigory_home", "scene": "Заботы Ульяны", "speaker": "Михаил Петров", "text": "Осенними вечерами Ульяна пряла шерсть для жены Буграша. За работой она вспоминала умершего мужа и годы нужды.", "kind": "n"}, {"bg": "grigory_home", "scene": "Заботы Ульяны", "speaker": "Михаил Петров", "text": "Сын вырос, и мать мечтала женить его. Но изба покосилась, а заработок Григория уходил на долги. Недоимка достигла девяти рублей.", "kind": "n"}, {"bg": "grigory_home", "scene": "Последняя лошадь", "speaker": "Михаил Петров", "text": "В хозяйстве не осталось коровы. Всё, что ещё могла сохранить Ульяна, — старая, захудалая лошадёнка.", "kind": "n"}, {"bg": "grigory_home", "scene": "Возвращение Григория", "speaker": "Михаил Петров", "text": "Григорий вернулся домой после разговора у Степана Лосева. Мать встретила его вопросами.", "kind": "n"}, {"bg": "grigory_home", "scene": "Разговор о свадьбе", "speaker": "Ульяна", "text": "Что это так долго? О чем говорили?", "kind": "d"}, {"bg": "grigory_home", "scene": "Разговор о свадьбе", "speaker": "Григорий", "text": "Известно о чем, о податях.", "kind": "d"}, {"bg": "grigory_home", "scene": "Разговор о свадьбе", "speaker": "Ульяна", "text": "Как же мы будем свадьбу справлять, сынок?", "kind": "d"}, {"bg": "grigory_home", "scene": "Разговор о свадьбе", "speaker": "Григорий", "text": "Какую свадьбу?", "kind": "d"}, {"bg": "grigory_home", "scene": "Разговор о свадьбе", "speaker": "Ульяна", "text": "Все о невестке думаю я, Гриша.", "kind": "d"}, {"bg": "grigory_home", "scene": "Разговор о свадьбе", "speaker": "Григорий", "text": "Кого же ты надумала в невестки?", "kind": "d"}, {"bg": "grigory_home", "scene": "Разговор о свадьбе", "speaker": "Ульяна", "text": "Поговорю вот с сестрой Аленой — может, у нее кто на примете есть.", "kind": "d"}, {"bg": "grigory_home", "scene": "Разговор о свадьбе", "speaker": "Григорий", "text": "А если ее выбор не по душе мне придется?", "kind": "d"}, {"bg": "grigory_home", "scene": "Разговор о свадьбе", "speaker": "Ульяна", "text": "Все на красоту смотришь, а то невдомек, что из красоты скирды не складывать.", "kind": "d"}, {"bg": "grigory_home", "scene": "Разговор о свадьбе", "speaker": "Григорий", "text": "Тяжело тебе одной, без помощницы, вижу я.", "kind": "d"}, {"bg": "grigory_home", "scene": "Тихая радость", "speaker": "Михаил Петров", "text": "От ласковых слов сына Ульяна прослезилась и украдкой смахнула слезу краем платка.", "kind": "n"}, {"bg": "yard_horse", "scene": "Первый снег", "speaker": "Михаил Петров", "text": "Выпал первый снег. Буграш собрался отправить хлебный обоз в Елабугу и велел Григорию готовиться к извозу.", "kind": "n"}, {"bg": "yard_horse", "scene": "Подготовка к дороге", "speaker": "Михаил Петров", "text": "Во дворе Григорий прилаживал к саням новые оглобли. Ульяна смотрела на него из окна: после тяжёлой работы сын снова отправлялся в путь.", "kind": "n"}, {"bg": "yard_horse", "scene": "Предупреждение Алёны", "speaker": "Михаил Петров", "text": "Скрипнула калитка. Во двор поспешно вошла Алёна, младшая сестра Ульяны.", "kind": "n"}, {"bg": "yard_horse", "scene": "Предупреждение Алёны", "speaker": "Алёна", "text": "Урядник к вам идет, Гриша!", "kind": "d"}, {"bg": "yard_horse", "scene": "Предупреждение Алёны", "speaker": "Григорий", "text": "А что ему у нас надо?", "kind": "d"}, {"bg": "yard_horse", "scene": "Предупреждение Алёны", "speaker": "Алёна", "text": "Подати собирает и недоимки. Иван Красный сказал.", "kind": "d"}, {"bg": "yard_horse", "scene": "Предупреждение Алёны", "speaker": "Михаил Петров", "text": "Алёна рассказала, что у Антона Камаева уже забрали последнюю тёлку. Она боялась, что теперь отнимут лошадь Григория.", "kind": "n"}, {"bg": "yard_horse", "scene": "Предупреждение Алёны", "speaker": "Алёна", "text": "Где-нибудь в лесу переждешь.", "kind": "d"}, {"bg": "yard_horse", "scene": "Предупреждение Алёны", "speaker": "Григорий", "text": "А если он и завтра явится? И послезавтра?", "kind": "d"}, {"bg": "yard_horse", "scene": "Гнев Григория", "speaker": "Михаил Петров", "text": "В отчаянии Григорий схватил топор и с силой воткнул его в порог амбара. Алёна испугалась его гнева.", "kind": "n"}, {"bg": "yard_horse", "scene": "Гнев Григория", "speaker": "Алёна", "text": "Не вздумай тут бушевать, а не то головы тебе не сносить.", "kind": "d"}, {"bg": "yard_horse", "scene": "Приход властей", "speaker": "Михаил Петров", "text": "Во двор вошли урядник Агафон Демьянович, староста Бектэмыр и понятые Иван Красный и Степан Журавль.", "kind": "n"}, {"bg": "grigory_home", "scene": "У окна", "speaker": "Михаил Петров", "text": "Алёна вбежала в дом. Ульяна увидела урядника из окна и случайно смахнула со стола берестяную солонку.", "kind": "n"}, {"bg": "grigory_home", "scene": "У окна", "speaker": "Ульяна", "text": "Что они ходят тут, зачем пришли?", "kind": "d"}, {"bg": "grigory_home", "scene": "У окна", "speaker": "Михаил Петров", "text": "Ульяна вспомнила о бочонке самогона, который берегла к свадьбе сына. Алёна помогла спрятать его в подполье.", "kind": "n"}, {"bg": "yard_empty", "scene": "Лошадь уводят", "speaker": "Михаил Петров", "text": "Из окна Ульяна увидела, как со двора выводят лошадь. Григорий стоял понурив голову.", "kind": "n"}, {"bg": "yard_empty", "scene": "Лошадь уводят", "speaker": "Ульяна", "text": "А лошадь они зачем?", "kind": "d"}, {"bg": "yard_empty", "scene": "Лошадь уводят", "speaker": "Григорий", "text": "Увели... за недоимку...", "kind": "d"}, {"bg": "winter_street", "scene": "На деревенской улице", "speaker": "Михаил Петров", "text": "Ульяна выбежала на улицу и вцепилась в повод. Для семьи потеря лошади означала потерю последней опоры хозяйства.", "kind": "n"}, {"bg": "winter_street", "scene": "На деревенской улице", "speaker": "Ульяна", "text": "Не дам! Хоть убейте, не дам!", "kind": "d"}, {"bg": "winter_street", "scene": "На деревенской улице", "speaker": "Агафон Демьянович", "text": "Убрать эту сумасшедшую!", "kind": "d"}, {"bg": "winter_street", "scene": "На деревенской улице", "speaker": "Михаил Петров", "text": "Григорий заслонил мать, испугавшись, что урядник её ударит. В суматохе он снял узду, и испуганная лошадь бросилась в сторону.", "kind": "n"}, {"bg": "winter_street", "scene": "На деревенской улице", "speaker": "Михаил Петров", "text": "Женщины и дети наблюдали из окон. Понятые вскоре поймали лошадь. Акмар видел всё у ворот дома своего зятя Ивана Красного.", "kind": "n"}, {"bg": "office_winter", "scene": "Решение Акмара", "speaker": "Михаил Петров", "text": "Акмар постоял в раздумье и направился к съезжей избе, куда ушли урядник и староста. Сам разговор в романе не показан.", "kind": "n"}, {"bg": "yard_horse", "scene": "Возвращение лошади", "speaker": "Михаил Петров", "text": "Вскоре Иван Красный привёл лошадь обратно во двор. Григорий и Алёна вышли ему навстречу.", "kind": "n"}, {"bg": "yard_horse", "scene": "Возвращение лошади", "speaker": "Григорий", "text": "Ты что это, дядя Иван?", "kind": "d"}, {"bg": "yard_horse", "scene": "Возвращение лошади", "speaker": "Иван Красный", "text": "Лошадь обратно привел тебе, Гриша.", "kind": "d"}, {"bg": "yard_horse", "scene": "Возвращение лошади", "speaker": "Михаил Петров", "text": "Иван объяснил: Акмар полностью уплатил недоимку за Григория. Старик сказал, что остался должен его покойному отцу.", "kind": "n"}, {"bg": "akmar_home", "scene": "В гостях у Акмара", "speaker": "Михаил Петров", "text": "Вечером Григорий и Ульяна пришли поблагодарить Акмара. Семья ужинала: старик сидел на стуле, а Дуня, Николай и их мать — на скамье.", "kind": "n"}, {"bg": "akmar_home", "scene": "Смущение Дуняши", "speaker": "Михаил Петров", "text": "Дуняша смутилась, увидев Григория с матерью: не свататься ли пришли? Она даже подумала спрятаться за кухонной перегородкой.", "kind": "n"}, {"bg": "akmar_home", "scene": "Благодарность Ульяны", "speaker": "Михаил Петров", "text": "Ульяна подошла к Акмару, опустилась перед ним на колени и поклонилась ему в ноги.", "kind": "n"}, {"bg": "akmar_home", "scene": "Благодарность Ульяны", "speaker": "Ульяна", "text": "До самой смерти своей не забуду твою доброту.", "kind": "d"}, {"bg": "akmar_home", "scene": "Гостеприимство", "speaker": "Мать Дуняши", "text": "Садись-ка лучше за стол, как раз к ужину угодили.", "kind": "d"}, {"bg": "akmar_home", "scene": "Гостеприимство", "speaker": "Мать Дуняши", "text": "Дуня, неси-ка ложки.", "kind": "d"}, {"bg": "akmar_home", "scene": "Слова Акмара", "speaker": "Михаил Петров", "text": "Григорий тоже хотел преклонить колени, но Акмар остановил его.", "kind": "n"}, {"bg": "akmar_home", "scene": "Слова Акмара", "speaker": "Акмар", "text": "Все мы должны помогать друг другу.", "kind": "d"}, {"bg": "akmar_home", "scene": "Слова Акмара", "speaker": "Акмар", "text": "Кто знает, что будет завтра — может, и тебе придется помочь нам.", "kind": "d"}, {"bg": "akmar_home", "scene": "Слова Акмара", "speaker": "Акмар", "text": "Чем богаты, тем и рады.", "kind": "d"}, {"bg": "akmar_home", "scene": "Вопрос Николая", "speaker": "Михаил Петров", "text": "Николай, младший брат Дуняши, смотрел то на деда, то на гостей, не понимая, что произошло.", "kind": "n"}, {"bg": "akmar_home", "scene": "Вопрос Николая", "speaker": "Николай", "text": "Что случилось, дедушка?", "kind": "d"}, {"bg": "akmar_home", "scene": "Конец второй главы", "speaker": "Акмар", "text": "Ничего не случилось, Николай. Просто горе приводит людей друг к другу.", "kind": "d"}];

