function switchChapter(n){
 if(![1,2,3].includes(n)||n===activeChapter)return;
 multanStorage.setItem('multan-progress-'+activeChapter,i);
 activeChapter=n;data=n===1?chapterOneData:n===2?chapterTwoData:chapterThreeData;sections=n===1?chapterOneSections:n===2?chapterTwoSections:chapterThreeSections;studyNotes=n===1?chapterOneNotes:n===2?chapterTwoNotes:chapterThreeNotes;studyQuestions=n===1?chapterOneQuestions:n===2?chapterTwoQuestions:chapterThreeQuestions;
 studyAnswers=readMultanAnswers(n);
 i=multanIndex('multan-progress-'+n,data.length);currentCharacter='';setBg();render();
 $('chapter1Btn').classList.toggle('selected',n===1);$('chapter2Btn').classList.toggle('selected',n===2);$('chapter3Btn').classList.toggle('selected',n===3);
 $('chapterHeading').textContent=n===1?'Глава первая':n===2?'Глава вторая':'Глава третья';$('chapterSub').textContent=n===1?'Старый Мултан':n===2?'Последняя лошадь':'После Масленицы — фрагмент для вычитки';
}
const baseRender=render;render=function(){baseRender();multanStorage.setItem('multan-progress-'+activeChapter,i);$('chapter1Btn').classList.toggle('selected',activeChapter===1);$('chapter2Btn').classList.toggle('selected',activeChapter===2);$('chapter3Btn').classList.toggle('selected',activeChapter===3)};
$('chapter1Btn').onclick=()=>switchChapter(1);$('chapter2Btn').onclick=()=>switchChapter(2);$('chapter3Btn').onclick=()=>switchChapter(3);
// The glossary uses existing portraits and chapter filters; descriptions distinguish book facts from reconstructions.
function showCharacters(){let filter=0;function paint(){let list=characterCards.filter(c=>filter===0||c.chapters.includes(filter));$('modalBody').innerHTML='<div class="char-filters"><button data-filter="0" class="'+(!filter?'selected':'')+'">Все</button><button data-filter="1" class="'+(filter===1?'selected':'')+'">Глава I</button><button data-filter="2" class="'+(filter===2?'selected':'')+'">Глава II</button><button data-filter="3" class="'+(filter===3?'selected':'')+'">Глава III</button></div><p class="char-note">Портреты — художественная реконструкция. Описания основаны на событиях романа; возраст и неописанные черты внешности не считаются установленными фактами.</p><div class="char-grid">'+list.map(c=>'<article class="char-card">'+(c.image?'<img loading="lazy" src="assets/'+c.image+'.webp" alt="Портрет: '+c.name+'">':'<div class="char-placeholder">Портрет будет добавлен</div>')+'<div><h3>'+c.name+'</h3><small>'+c.chapters.map(n=>'Глава '+(n===1?'I':n===2?'II':'III')).join(' · ')+'</small><p><b>'+c.role+'</b></p><p>'+c.details+'</p></div></article>').join('')+'</div>';$('modalBody').querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=+b.dataset.filter;paint()})}popup('Персонажи романа', '');paint()}
$('charactersOpen').onclick=showCharacters;
// Correct answer storage for the selected chapter; preserve original chapter-one implementation otherwise.
const originalRenderStudy=renderStudy;
renderStudy=function(){originalRenderStudy();if(activeChapter>=2){$('archiveCard').innerHTML='<p>Фотографический архив первой главы доступен при переключении на главу I. Иллюстрации второй главы — художественные реконструкции.</p>';}};
// Custom chapter 2 quiz, chapter 1 remains unchanged.
const oldRenderStudy2=renderStudy;
renderStudy=function(){if(activeChapter===1){oldRenderStudy2();return;}const item=data[i],note=studyNotes[item.bg]||studyNotes.late_autumn;$('note').hidden=studyTab!=='fact';$('quizCard').hidden=studyTab!=='quiz';$('archiveCard').hidden=studyTab!=='archive';['fact','quiz','archive'].forEach((x,k)=>$( ['tabFact','tabQuiz','tabArchive'][k]).classList.toggle('selected',studyTab===x));$('note').innerHTML='<div class="tag">Книга и эпоха</div><h4>'+note[0]+'</h4><p>'+note[1]+'</p><div class="reflection"><b>Подумайте:</b> '+note[2]+'</div>';
 const available=studyQuestions.map((q,k)=>({...q,k})).filter(q=>i>=q.from),q=available.at(-1);if(!q){$('quizCard').innerHTML='<p>Вопросы откроются по мере чтения.</p>';return;}const answer=studyAnswers[q.k];$('quizCard').innerHTML='<div class="tag">Вопрос '+(q.k+1)+' из '+studyQuestions.length+'</div><p class="question">'+q.q+'</p>'+q.a.map((a,k)=>'<button class="answer '+(answer===k?(k===q.c?'right':'wrong'):'')+'" data-choice="'+k+'" '+(answer!==undefined?'disabled':'')+'>'+a+'</button>').join('')+(answer!==undefined?'<p class="explanation">'+q.why+'</p>':'')+'<button class="retry">Ответить заново</button>';$('quizCard').querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{studyAnswers[q.k]=+b.dataset.choice;saveMultanAnswers(activeChapter,studyAnswers);renderStudy()});$('quizCard').querySelector('.retry').onclick=()=>{delete studyAnswers[q.k];saveMultanAnswers(activeChapter,studyAnswers);renderStudy()};};
render();

// Navigation fix: show the questions panel when the header button is pressed.
$('quizOpen').onclick=()=>{const home=document.getElementById('homeScreen');if(home&&!home.hidden){home.hidden=true;document.body.classList.remove('on-home')}studyTab='quiz';renderStudy();const panel=document.getElementById('quizCard');if(panel){panel.hidden=false;panel.scrollIntoView({behavior:'smooth',block:'center'})}};
